import math, time, heapq
from Bio.PDB import PDBParser

p = PDBParser(QUIET=True)
s = p.get_structure('m', '/task/input/models/model_01.pdb')
atoms = [a for a in s.get_atoms() if a.element != 'H']
print('atoms', len(atoms))

t = time.time()
blocked = set()
for a in atoms:
    cx, cy, cz = map(float, a.coord)
    xlo = math.floor(cx - 3.0); xhi = math.ceil(cx + 3.0)
    ylo = math.floor(cy - 3.0); yhi = math.ceil(cy + 3.0)
    zlo = math.floor(cz - 3.0); zhi = math.ceil(cz + 3.0)
    for x in range(xlo, xhi + 1):
        dx2 = (x - cx) ** 2
        for y in range(ylo, yhi + 1):
            dy2 = (y - cy) ** 2
            for z in range(zlo, zhi + 1):
                if dx2 + dy2 + (z - cz) ** 2 < 9.0:
                    blocked.add((x, y, z))
print('blocked', len(blocked), 'build_s', round(time.time()-t, 2))

N = []
for dx in (-1, 0, 1):
    for dy in (-1, 0, 1):
        for dz in (-1, 0, 1):
            if dx == dy == dz == 0:
                continue
            N.append(((dx, dy, dz), math.sqrt(dx*dx + dy*dy + dz*dz)))

def surface_ok(P, Q, limit=34.0, tether=7.0):
    px, py, pz = map(float, P)
    qx, qy, qz = map(float, Q)
    heap = []
    best = {}
    for x in range(math.floor(px - tether), math.ceil(px + tether) + 1):
        for y in range(math.floor(py - tether), math.ceil(py + tether) + 1):
            for z in range(math.floor(pz - tether), math.ceil(pz + tether) + 1):
                s = (x, y, z)
                if s in blocked:
                    continue
                dp = math.sqrt((x-px)**2 + (y-py)**2 + (z-pz)**2)
                if dp > tether + 1e-12:
                    continue
                h = math.sqrt((x-qx)**2 + (y-qy)**2 + (z-qz)**2)
                if dp + h > limit + 1e-9:
                    continue
                best[s] = dp
                heapq.heappush(heap, (dp + h, dp, s))
    while heap:
        f, g, u = heapq.heappop(heap)
        if f > limit + 1e-9:
            return False
        if abs(best.get(u, 1e9) - g) > 1e-12:
            continue
        dq = math.sqrt((u[0]-qx)**2 + (u[1]-qy)**2 + (u[2]-qz)**2)
        if dq <= tether + 1e-12 and g + dq <= limit + 1e-9:
            return True
        ux, uy, uz = u
        for (dx, dy, dz), step in N:
            v = (ux+dx, uy+dy, uz+dz)
            if v in blocked:
                continue
            ng = g + step
            if ng > limit + 1e-9:
                continue
            hv = math.sqrt((v[0]-qx)**2 + (v[1]-qy)**2 + (v[2]-qz)**2)
            if ng + hv > limit + 1e-9:
                continue
            if ng < best.get(v, 1e9) - 1e-12:
                best[v] = ng
                heapq.heappush(heap, (ng + hv, ng, v))
    return False

ca = {}
for ch in s[0]:
    for r in ch:
        if r.resname == 'LYS' and 'CA' in r:
            ca[(ch.id, r.id[1])] = r['CA'].coord

tests = [
    ('XL001_A56_B56', ('A',56), ('B',56)),
    ('XL003_C72_D72', ('C',72), ('D',72)),
    ('XL002_C80_A20', ('C',80), ('A',20)),
    ('XL002_D80_B20', ('D',80), ('B',20)),
]
for name, ka, kb in tests:
    P, Q = ca.get(ka), ca.get(kb)
    if P is None or Q is None:
        print(name, 'missing')
        continue
    d = float(((P-Q)**2).sum()**0.5)
    t = time.time()
    ok = surface_ok(P, Q)
    print(name, 'euclid', round(d,2), 'surface_ok', ok, 'time', round(time.time()-t,4))
